// DANGEROUS: Opens up XSS if userContent contains malicious scripts
export function UnsafeRender({ userContent }) {
  return <div dangerouslySetInnerHTML={{ __html: userContent }} />;
}

// SAFE: Use a dedicated sanitization library like DOMPurify if raw HTML is mandatory
import DOMPurify from 'dompurify';

export function SafeRender({ userContent }) {
  const cleanHtml = DOMPurify.sanitize(userContent);
  return <div dangerouslySetInnerHTML={{ __html: cleanHtml }} />;
}
